/*
 Problem: 2058. Find the Minimum and Maximum Number of Nodes Between Critical Points
 Language: cpp
 Runtime: 4 ms (55.94%)
 Memory: 124.6 MB (55.87%)
 Tags: Linked List
*/
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        int pos = 1, first = -1, prev = -1;
        int mn = INT_MAX;

        ListNode *a = head, *b = head->next;

        while (b && b->next) {
            if ((b->val > a->val && b->val > b->next->val) ||
                (b->val < a->val && b->val < b->next->val)) {

                if (first == -1) {
                    first = pos;
                } else {
                    mn = min(mn, pos - prev);
                }

                prev = pos;
            }

            a = b;
            b = b->next;
            pos++;
        }

        if (first == prev) return {-1, -1};

        return {mn, prev - first};
    }
};
